    morphIds = wordsOf(stackValue(6));
    edgeCounts = wordsOf(stackValue(5));
    alphaMask = wordsOf(stackValue(4));
    affectedBits = bytesOf(stackValue(3));
    contour = float32Of(stackValue(2));
    targetWidth = aNumber;
    targetHeight = otherNumber;
