var pvt_lineWPFromXytoXy = notYetTranslated;
var pvt_quadraticBezierFromXytoXycontrolXy = notYetTranslated;
var pvt_quadraticBezierWPFromXytoXycontrolXy = notYetTranslated;
var pvt_cubicBezierFromXytoXycontrol1Xycontrol2Xy = notYetTranslated;
var pvt_cubicBezierWPFromXytoXycontrol1Xycontrol2Xy = notYetTranslated;
